#!/usr/bin/env python3
"""Encoder V7 项目一键恢复脚本
用法: python restore.py
"""
import base64, zlib, json, os

DATA = """"""

files = json.loads(zlib.decompress(base64.b64decode(DATA)))
for name, content in files.items():
    with open(name, 'w', encoding='utf-8') as f:
        f.write(content)
    print(f"  [OK] {name} ({len(content)} chars)")
print("\nEncoder V7 项目恢复完成! 文件: util.py, encoder.py, decoder.py")
